import crypto from "node:crypto";
import {query} from "./database.mjs";
export function createHandler(bindings){
const env={...bindings,ARA_PUBLIC_ORIGIN:"https://anthares-ara-vercel-reserve.vercel.app"};






const ORIGIN=(env.ARA_PUBLIC_ORIGIN||'https://anthares-remote-mcp-primary.vercel.app').replace(/\/$/,'');
const TOKEN_SECRET=env.ARA_OAUTH_TOKEN_SECRET||'';
const OWNER_HASH=env.ARA_OWNER_APPROVAL_HASH||'';
const DEFAULT_DEVICE=env.ANTHARES_DEVICE_ID||'DESKTOP-FTDK0HP';
const DEVICE_HASH_BASE='https://raw.githubusercontent.com/UniversoAnthares/anthares-kwai-runner/main/anthares-remote-agent/devices';
const SCOPES=new Set(['ara.read','ara.write']);
const SAFE_RETRY=new Set(['ping','system_info','process_list','clipboard_get','file_stat','file_list','file_read','file_read_chunk','job_list','job_status','job_logs']);
const WRITE_TOOLS=new Set(['remote_exec','clipboard_set','file_write','file_write_chunk','remote_job_start','remote_job_cancel','process_start','process_kill','service_start','service_stop','file_mkdir','file_remove','file_rename','file_copy','file_write_atomic']);
const pool={query:(text,params)=>query(env,text,params)};
const hashCache=new Map();
let schemaReady=false;

function reply(res,status,body,headers={}){res.statusCode=status;for(const[k,v]of Object.entries({'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff',...headers}))res.setHeader(k,v);res.end(JSON.stringify(body));}
function html(res,status,body){res.statusCode=status;res.setHeader('Content-Type','text/html; charset=utf-8');res.setHeader('Cache-Control','no-store');res.setHeader('Content-Security-Policy',"default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'");res.setHeader('Referrer-Policy','no-referrer');res.setHeader('X-Content-Type-Options','nosniff');res.end(body);}
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function b64url(v){return Buffer.from(v).toString('base64url');}
function safeEq(a,b){const aa=Buffer.from(String(a));const bb=Buffer.from(String(b));return aa.length===bb.length&&crypto.timingSafeEqual(aa,bb);}
function sha256hex(v){return crypto.createHash('sha256').update(String(v)).digest('hex');}
function sha256b64(v){return crypto.createHash('sha256').update(String(v)).digest('base64url');}
function randomId(){return crypto.randomBytes(16).toString('hex');}
function formBody(req){if(req.body&&typeof req.body==='object'&&!Buffer.isBuffer(req.body))return new URLSearchParams(req.body);if(typeof req.body==='string')return new URLSearchParams(req.body);return new URLSearchParams();}
function jsonBody(req){if(req.body&&typeof req.body==='object'&&!Buffer.isBuffer(req.body))return req.body;if(typeof req.body==='string'){try{return JSON.parse(req.body)}catch{return {}}}return {};}
function bearer(req){const m=/^Bearer\s+(.+)$/i.exec(req.headers.authorization||'');return m?m[1]:'';}
function validClient(v){return v==='https://chatgpt.com/oauth/client.json'||/^https:\/\/chatgpt\.com\/oauth\/[A-Za-z0-9_-]{8,}\/client\.json$/.test(v||'');}
function validRedirect(v){return v==='https://chatgpt.com/connector_platform_oauth_redirect'||/^https:\/\/chatgpt\.com\/connector\/oauth\/[A-Za-z0-9_-]+$/.test(v||'');}
function parseScopes(v){const xs=String(v||'ara.read ara.write').trim().split(/\s+/).filter(Boolean);if(!xs.length||xs.some(x=>!SCOPES.has(x)))return null;return [...new Set(xs)];}
function signToken(payload){if(TOKEN_SECRET.length<32)throw new Error('oauth_not_configured');const body=b64url(JSON.stringify(payload));const sig=crypto.createHmac('sha256',TOKEN_SECRET).update(body).digest('base64url');return `${body}.${sig}`;}
function verifyToken(token,type){if(TOKEN_SECRET.length<32||!token)return null;const [body,sig,extra]=String(token).split('.');if(!body||!sig||extra)return null;const expSig=crypto.createHmac('sha256',TOKEN_SECRET).update(body).digest('base64url');if(!safeEq(sig,expSig))return null;try{const p=JSON.parse(Buffer.from(body,'base64url').toString('utf8'));if(p.typ!==type||p.iss!==ORIGIN||p.aud!==ORIGIN||p.exp<=Math.floor(Date.now()/1000)||!Array.isArray(p.scp))return null;return p}catch{return null}}
function issueTokens(clientId,scopes){const now=Math.floor(Date.now()/1000),base={iss:ORIGIN,aud:ORIGIN,sub:'anthares-owner',cid:clientId,scp:scopes};return{access_token:signToken({...base,typ:'access',iat:now,exp:now+900,jti:randomId()}),token_type:'Bearer',expires_in:900,refresh_token:signToken({...base,typ:'refresh',iat:now,exp:now+30*86400,jti:randomId()}),scope:scopes.join(' ')}};
function challenge(){return `Bearer resource_metadata="${ORIGIN}/.well-known/oauth-protected-resource", scope="ara.read ara.write"`;}

async function ensureSchema(){if(schemaReady)return;const r=await pool.query("SELECT to_regclass('public.ara_oauth_consumed') AS replay,to_regclass('public.ara_reserve_jobs') AS jobs");if(!r.rows[0]?.replay||!r.rows[0]?.jobs)throw new Error("shared_schema_missing");schemaReady=true;}
async function consume(kind,jti,exp){await ensureSchema();const r=await pool.query(`INSERT INTO ara_oauth_consumed(kind,issuer,jti,expires_at) VALUES($1,$2,$3,to_timestamp($4)) ON CONFLICT DO NOTHING RETURNING jti`,[kind,ORIGIN,jti,Number(exp)]);return r.rowCount===1;}
async function expectedDeviceHash(device){const c=hashCache.get(device);if(c&&Date.now()-c.at<60000)return c.hash;const r=await fetch(`${DEVICE_HASH_BASE}/${encodeURIComponent(device)}.sha256`,{headers:{'User-Agent':'AntharesRemoteVercel/1.0','cache-control':'no-cache'}});if(!r.ok)return '';const h=(await r.text()).trim().toLowerCase();if(!/^[0-9a-f]{64}$/.test(h))return '';hashCache.set(device,{hash:h,at:Date.now()});return h;}
async function deviceAuth(req){const device=String(req.headers['x-anthares-device']||'').trim();if(!/^[A-Za-z0-9_.-]{1,200}$/.test(device))return{ok:false,device:''};const token=bearer(req);if(!token)return{ok:false,device};const expected=await expectedDeviceHash(device);return{ok:!!expected&&safeEq(sha256hex(token),expected),device};}
async function mcpControlKey(){if(env.ARA_CONTROL_PUBLIC_KEY)return env.ARA_CONTROL_PUBLIC_KEY;const r=await fetch('https://anthares-ara-mcp.anthares1.workers.dev/.well-known/ara-control-key',{headers:{'User-Agent':'AntharesARAVercel/1.0','cache-control':'no-cache'}});if(!r.ok)throw new Error('mcp_control_key_unavailable');const pem=await r.text();if(!pem.includes('BEGIN PUBLIC KEY')||pem.length>4096)throw new Error('mcp_control_key_invalid');return pem;}
function controlTarget(req,route){const u=new URL(req.url,ORIGIN);const pairs=[];for(const[k,v]of u.searchParams.entries())if(k!=='route')pairs.push([k,v]);const qs=new URLSearchParams(pairs).toString();return `/${route}${qs?'?'+qs:''}`;}
async function verifyMcpControl(req,route){if(String(req.headers['x-ara-signer']||'')!=='anthares-remote-mcp')return false;const ts=String(req.headers['x-ara-timestamp']||''),sig=String(req.headers['x-ara-signature']||'');const n=Number(ts);if(!Number.isFinite(n)||Math.abs(Date.now()-n)>30000||!sig)return false;const raw=req.body===undefined||req.body===null?'':(typeof req.body==='string'?req.body:JSON.stringify(req.body));const payload=Buffer.from(`${ts}\n${String(req.method||'GET').toUpperCase()}\n${controlTarget(req,route)}\n${raw}`);let pem;try{pem=await mcpControlKey();if(!crypto.verify(null,payload,pem,Buffer.from(sig,'base64url')))return false;}catch{return false;}return consume('mcp_signature',sig,Math.floor(Date.now()/1000)+60);}

async function reap(device){await pool.query(`UPDATE ara_reserve_jobs SET status=CASE WHEN type=ANY($2::text[]) THEN 'queued' ELSE 'uncertain' END,lease_until=NULL WHERE device_id=$1 AND status='leased' AND lease_until<=now() AND expires_at>now()`,[device,[...SAFE_RETRY]]);await pool.query(`UPDATE ara_reserve_jobs SET status='expired',lease_until=NULL,result=COALESCE(result,'{"ok":false,"error":"execution_outcome_unknown","reconciled":"expired_after_deadline"}'::jsonb) WHERE device_id=$1 AND status IN ('queued','uncertain') AND expires_at<=now()`,[device]);await pool.query(`UPDATE ara_reserve_jobs SET status='uncertain',lease_until=NULL WHERE device_id=$1 AND status='leased' AND expires_at<=now() AND NOT(type=ANY($2::text[]))`,[device,[...SAFE_RETRY]]);await pool.query(`UPDATE ara_reserve_jobs SET status='expired',lease_until=NULL WHERE device_id=$1 AND status='leased' AND expires_at<=now() AND type=ANY($2::text[])`,[device,[...SAFE_RETRY]]);}
async function status(device){await reap(device);const[d,c]=await Promise.all([pool.query(`SELECT heartbeat,seen_at FROM ara_reserve_devices WHERE device_id=$1`,[device]),pool.query(`SELECT count(*) FILTER(WHERE status='queued') queued,count(*) FILTER(WHERE status='leased') leased,count(*) FILTER(WHERE status='uncertain') uncertain FROM ara_reserve_jobs WHERE device_id=$1`,[device])]);const row=d.rows[0],counts=c.rows[0]||{};const seen=row?.seen_at?new Date(row.seen_at):null;const age=seen?(Date.now()-seen.getTime())/1000:null;return{heartbeat:row?.heartbeat||null,seen_at:seen?.toISOString()||null,connected:age!==null&&age>=0&&age<=90,queued:Number(counts.queued||0),leased:Number(counts.leased||0),uncertain:Number(counts.uncertain||0),backend:'vercel-neon'};}
async function heartbeat(device,body){await pool.query(`INSERT INTO ara_reserve_devices(device_id,heartbeat,seen_at) VALUES($1,$2::jsonb,now()) ON CONFLICT(device_id) DO UPDATE SET heartbeat=excluded.heartbeat,seen_at=excluded.seen_at`,[device,JSON.stringify({...body,seen_at:new Date().toISOString()})]);return{ok:true};}
async function createJob(device,type,args,timeout=30,idem=''){const t=Math.max(1,Math.min(Number(timeout||30),100));if(idem){const old=await pool.query(`SELECT * FROM ara_reserve_jobs WHERE device_id=$1 AND idempotency_key=$2 LIMIT 1`,[device,idem]);if(old.rowCount)return old.rows[0];}const id=randomId();const r=await pool.query(`INSERT INTO ara_reserve_jobs(id,device_id,type,args,timeout_seconds,created_at,expires_at,status,attempts,lease_until,idempotency_key,result) VALUES($1,$2,$3,$4::jsonb,$5,now(),now()+($6||' seconds')::interval,'queued',0,NULL,$7,NULL) ON CONFLICT(device_id,idempotency_key) WHERE idempotency_key IS NOT NULL DO UPDATE SET device_id=excluded.device_id RETURNING *`,[id,device,type,JSON.stringify(args||{}),t,String(t+30),idem||null]);return r.rows[0];}
async function leaseNext(device){await reap(device);const r=await pool.query(`WITH picked AS (SELECT id FROM ara_reserve_jobs WHERE device_id=$1 AND status='queued' AND expires_at>now() ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1) UPDATE ara_reserve_jobs j SET status='leased',attempts=j.attempts+1,lease_until=now()+interval '35 seconds' FROM picked WHERE j.id=picked.id RETURNING j.*`,[device]);return r.rows[0]||null;}
async function submitResult(device,id,result){const r=await pool.query(`SELECT status,result FROM ara_reserve_jobs WHERE id=$1 AND device_id=$2`,[id,device]);if(!r.rowCount)return{status:404,error:'unknown_job_or_wrong_device'};const row=r.rows[0];if(['done','failed','expired'].includes(row.status)){if(JSON.stringify(row.result||{})===JSON.stringify(result||{}))return{status:200,duplicate:true};return{status:409,error:'result_conflict'};}if(!['leased','uncertain'].includes(row.status))return{status:409,error:'job_not_leased'};await pool.query(`UPDATE ara_reserve_jobs SET status=$1,result=$2::jsonb,lease_until=NULL WHERE id=$3 AND device_id=$4`,[result?.ok?'done':'failed',JSON.stringify(result||{}),id,device]);return{status:200,ok:true};}
async function getJob(device,id){await reap(device);const r=await pool.query(`SELECT * FROM ara_reserve_jobs WHERE id=$1 AND device_id=$2`,[id,device]);return r.rows[0]||null;}
async function execute(type,args={},timeout=30,device=DEFAULT_DEVICE){const idem=`mcp-${randomId()}`;const job=await createJob(device,type,args,timeout,idem);const deadline=Date.now()+(Math.min(Number(timeout||30),100)+8)*1000;let cur=job;while(Date.now()<deadline){cur=await getJob(device,job.id);if(!cur)throw new Error('job_lost');if(['done','failed','expired','uncertain'].includes(cur.status))break;await new Promise(r=>setTimeout(r,250));}if(!cur)return{ok:false,error:'job_lost'};if(cur.status==='uncertain')return{ok:false,status:'uncertain',job_id:cur.id,error:'execution_outcome_unknown'};if(!['done','failed'].includes(cur.status))return{ok:false,status:cur.status,job_id:cur.id,error:'timeout_waiting_for_device'};const out=cur.result||{};return{ok:!!out.ok,status:cur.status,job_id:cur.id,output:out.output??null,error:out.error??null,started_at:out.started_at??null,ended_at:out.ended_at??null};}
function text(v){return{content:[{type:'text',text:typeof v==='string'?v:JSON.stringify(v,null,2)}]};}

function metadata(res){reply(res,200,{issuer:ORIGIN,authorization_endpoint:`${ORIGIN}/oauth/authorize`,token_endpoint:`${ORIGIN}/oauth/token`,response_types_supported:['code'],grant_types_supported:['authorization_code','refresh_token'],code_challenge_methods_supported:['S256'],token_endpoint_auth_methods_supported:['none'],scopes_supported:[...SCOPES],client_id_metadata_document_supported:true,authorization_response_iss_parameter_supported:true});}

return async function handler(req,res){try{await ensureSchema();const route=String(req.query?.route||'').replace(/^\/+|\/+$/g,'');
if(req.method==='GET'&&route==='health'){let db=true;try{await pool.query('SELECT 1')}catch{db=false}const s=await status(DEFAULT_DEVICE).catch(()=>({connected:false}));return reply(res,db&&TOKEN_SECRET.length>=32&&OWNER_HASH.length===64?200:503,{ok:db&&TOKEN_SECRET.length>=32&&OWNER_HASH.length===64,service:'anthares-remote-primary',provider:'vercel',state:'neon',cloudflare_dependency:false,oauth:true,mcp:true,device_connected:!!s.connected,device_seen_at:s.seen_at||null});}
if(req.method==='GET'&&route==='well-known/oauth-protected-resource')return reply(res,200,{resource:ORIGIN,authorization_servers:[ORIGIN],scopes_supported:[...SCOPES],resource_documentation:'https://github.com/UniversoAnthares/anthares-kwai-runner'});
if(req.method==='GET'&&(route==='well-known/oauth-authorization-server'||route==='well-known/openid-configuration'))return metadata(res);
if(req.method==='GET'&&route==='oauth/authorize'){const u=new URL(req.url,ORIGIN),clientId=u.searchParams.get('client_id')||'',redirectUri=u.searchParams.get('redirect_uri')||'',responseType=u.searchParams.get('response_type')||'',cc=u.searchParams.get('code_challenge')||'',method=u.searchParams.get('code_challenge_method')||'',resource=u.searchParams.get('resource')||ORIGIN,scopes=parseScopes(u.searchParams.get('scope'));if(!validClient(clientId)||!validRedirect(redirectUri)||responseType!=='code'||method!=='S256'||cc.length<43||resource!==ORIGIN||!scopes)return reply(res,400,{error:'invalid_request'});const tx=signToken({typ:'oauth_pending',iss:ORIGIN,aud:ORIGIN,exp:Math.floor(Date.now()/1000)+600,jti:randomId(),clientId,redirectUri,challenge:cc,scopes,scp:scopes,state:u.searchParams.get('state')||''});return html(res,200,`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Anthares Remote</title></head><body><main><h1>Anthares Remote</h1><p>Digite o código de autorização do Anthares Remote.</p><form method="post" action="/oauth/authorize"><input type="hidden" name="tx" value="${esc(tx)}"><label>Código <input type="password" name="approval" autocomplete="one-time-code" required autofocus></label><button type="submit">Autorizar</button></form></main></body></html>`);}
if(req.method==='POST'&&route==='oauth/authorize'){const b=formBody(req),p=verifyToken(b.get('tx')||'','oauth_pending');if(!p)return reply(res,400,{error:'authorization_expired'});if(!safeEq(sha256hex(b.get('approval')||''),OWNER_HASH))return reply(res,403,{error:'authorization_denied'});if(!(await consume('oauth_pending',p.jti,p.exp)))return reply(res,400,{error:'authorization_replayed'});const code=signToken({typ:'oauth_code',iss:ORIGIN,aud:ORIGIN,exp:Math.floor(Date.now()/1000)+300,jti:randomId(),clientId:p.clientId,redirectUri:p.redirectUri,challenge:p.challenge,scopes:p.scopes,scp:p.scopes});const target=new URL(p.redirectUri);target.searchParams.set('code',code);if(p.state)target.searchParams.set('state',p.state);target.searchParams.set('iss',ORIGIN);res.statusCode=302;res.setHeader('Location',target.toString());res.setHeader('Cache-Control','no-store');return res.end();}
if(req.method==='POST'&&route==='oauth/token'){const b=formBody(req),grant=b.get('grant_type')||'',clientId=b.get('client_id')||'';if(!validClient(clientId))return reply(res,400,{error:'invalid_client'});if(grant==='authorization_code'){const p=verifyToken(b.get('code')||'','oauth_code');if(!p||p.clientId!==clientId||p.redirectUri!==(b.get('redirect_uri')||''))return reply(res,400,{error:'invalid_grant'});const verifier=b.get('code_verifier')||'';if(verifier.length<43||!safeEq(sha256b64(verifier),p.challenge))return reply(res,400,{error:'invalid_grant'});if(!(await consume('authorization_code',p.jti,p.exp)))return reply(res,400,{error:'invalid_grant'});return reply(res,200,issueTokens(clientId,p.scopes));}if(grant==='refresh_token'){const p=verifyToken(b.get('refresh_token')||'','refresh');if(!p||p.cid!==clientId)return reply(res,400,{error:'invalid_grant'});if(!(await consume('refresh_token',p.jti,p.exp)))return reply(res,400,{error:'invalid_grant'});return reply(res,200,issueTokens(clientId,p.scp));}return reply(res,400,{error:'unsupported_grant_type'});}
if(route==='mcp'){if(req.method!=='POST'){res.statusCode=405;res.setHeader('Allow','POST');return res.end();}const tok=verifyToken(bearer(req),'access');if(!tok)return reply(res,401,{error:'unauthorized'},{'WWW-Authenticate':challenge()});const rpc=jsonBody(req);const tool=rpc&&!Array.isArray(rpc)&&rpc.method==='tools/call'&&typeof rpc.params?.name==='string'?rpc.params.name:'';const write=WRITE_TOOLS.has(tool),required=write?'ara.write':'ara.read';if(!tok.scp.includes(required))return reply(res,403,{error:'insufficient_scope',required_scope:required},{'WWW-Authenticate':challenge()});const transport=new StreamableHTTPServerTransport({sessionIdGenerator:undefined});const server=makeMcp();await server.connect(transport);await transport.handleRequest(req,res,rpc);res.on('close',()=>transport.close().catch(()=>{}));return;}
if(route==='v1/mcp/status'&&req.method==='GET'){if(!(await verifyMcpControl(req,route)))return reply(res,401,{error:'unauthorized'});const device=String(req.query?.device_id||DEFAULT_DEVICE);return reply(res,200,await status(device));}
if(route==='v1/mcp/execute'&&req.method==='POST'){if(!(await verifyMcpControl(req,route)))return reply(res,401,{error:'unauthorized'});const b=jsonBody(req),device=String(b.device_id||DEFAULT_DEVICE),type=String(b.type||''),args=b.args&&typeof b.args==='object'?b.args:{},timeout=Math.max(1,Math.min(Number(b.timeout_seconds||30),100));if(!type)return reply(res,400,{error:'missing_type'});return reply(res,200,await execute(type,args,timeout,device));}
if(route==='v1/mcp/oauth/consume'&&req.method==='POST'){if(!(await verifyMcpControl(req,route)))return reply(res,401,{error:'unauthorized'});const b=jsonBody(req),kind=String(b.kind||''),issuer=String(b.issuer||''),jti=String(b.jti||''),exp=Number(b.exp||0);if(!kind||!issuer||!jti||!Number.isFinite(exp)||exp<=Math.floor(Date.now()/1000))return reply(res,400,{error:'invalid_replay_record'});await ensureSchema();const q=await pool.query(`INSERT INTO ara_oauth_consumed(kind,issuer,jti,expires_at) VALUES($1,$2,$3,to_timestamp($4)) ON CONFLICT DO NOTHING RETURNING jti`,[kind,issuer,jti,exp]);return reply(res,q.rowCount===1?200:409,{ok:q.rowCount===1,duplicate:q.rowCount!==1});}
if(route==='v1/device/auth-check'&&req.method==='GET'){const a=await deviceAuth(req);if(!a.ok)return reply(res,401,{ok:false,error:'unauthorized'});return reply(res,200,{ok:true,backend:'vercel-neon'});}
if(route==='v1/device/status'&&req.method==='GET'){const a=await deviceAuth(req);if(!a.ok)return reply(res,401,{error:'unauthorized'});return reply(res,200,await status(a.device));}
if(route==='v1/device/heartbeat'&&req.method==='POST'){const a=await deviceAuth(req);if(!a.ok)return reply(res,401,{error:'unauthorized'});await heartbeat(a.device,jsonBody(req));return reply(res,200,{ok:true,backend:'vercel-neon'});}
if(route==='v1/device/jobs/next'&&req.method==='GET'){const a=await deviceAuth(req);if(!a.ok)return reply(res,401,{error:'unauthorized'});const job=await leaseNext(a.device);if(!job){res.statusCode=204;return res.end();}return reply(res,200,{job});}
const m=route.match(/^v1\/device\/jobs\/([A-Za-z0-9_-]{1,100})\/result$/);if(m&&req.method==='POST'){const a=await deviceAuth(req);if(!a.ok)return reply(res,401,{error:'unauthorized'});const out=await submitResult(a.device,m[1],jsonBody(req));return reply(res,out.status,out.error?{error:out.error}:{ok:true,duplicate:!!out.duplicate});}
return reply(res,404,{error:'not_found',route});
}catch(e){console.error('ara-standby',e?.code||'request_failed');return reply(res,500,{error:'internal_error'});}}

}
